UPDATE ry_duanju.dj_script SET endings_json = '[{"id": "palace.end1", "type": "hidden", "priority": 100, "title": "宫斗冠军是总账会计", "text": "旧库编号与任命副本解释了重复记账的来源，你完成核验。传说中的冷宫从此改叫清静办公室，算盘成为全剧最有用的道具。", "condition": {"minStats": {"evidence": 4}, "maxStats": {"anger": 42}}, "posterTag": "隐藏彩蛋", "hint": "累计搜证材料 >= 4 且反派怒气 <= 42 方可拼合全部真相"}, {"id": "palace.end2", "type": "subversive", "priority": 90, "title": "本宫只想按时吃糕", "text": "你多次拒绝阵营比赛，推行直白通知与公开分配。赏花宴没有人争宠，大家在认真讨论下一炉桂花糕能不能少甜一点。", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3 且未触及隐藏或烂尾即可解锁"}, {"id": "palace.end3", "type": "unfinished", "priority": 80, "title": "密旨待附八十张明细", "text": "你热衷恭迎，没留下充分记录。密旨后面被订上长长的待办，柳总管宣布新的规矩是先学会填明细，片尾比片头更像开工。", "condition": {"minStats": {"anger": 60}, "maxStats": {"evidence": 2}}, "posterTag": "喜剧烂尾", "hint": "反派怒气累计 >= 60 且搜证材料 <= 2 时触发翻车烂尾"}, {"id": "palace.end4", "type": "triumph", "priority": 70, "title": "穿越第一课别重复报销", "text": "你用清楚证据完成核账，把复杂宫规改成可执行流程。团子掌勺按人数开炉，宫廷终于实现最朴素的稳定，人人有糕。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "稳健走完主线（未触发隐藏/反套路/烂尾）自动保底达成"}]', version = version + 1 WHERE script_id = 'script_09_palace';
